        ...(base.definition as WorkflowDefinition),
        id: goal.pluginId,
        name: goal.name,
        version: "generated",
        actions: [
          ...(base.definition as WorkflowDefinition).actions,
          ...(goal.extensions?.actions ?? []).filter(
            (a) =>
              !(base.definition as WorkflowDefinition).actions.some(
                (old) => old.id === a.id,
              ),
          ),
        ],
        fields: [
          ...goal.fields.map((f) => ({
            key: f.key,
            label: f.label,
            type: "text" as const,
            required: f.required,
          })),
          ...(goal.extensions?.fields ?? []),
        ],
      };
