            if (!member)
              throw new Error(
                `能力提供者不是候选辅助成员：${declaration.provider}`,
              );
            if (!member.enabled) continue;
            if (!memberRegistrations.has(pluginId)) {
              const registry = new ExtensionRegistry();
              const installs = await Promise.all(
                resolveVersionMembers(candidate)
                  .filter((m) => m.enabled)
                  .map(async (m) => ({
