                    role: m.role,
                    contribution: await runtime
                      .invoke<ExtensionContribution>(
                        "contribute",
                        undefined,
                        m.pluginId,
                      )
                      .catch(() => emptyContribution()),
                    workflowFields: m.role === "workflow" ? actual.fields : [],
