              "decide",
              {
                task: {
                  id: "member-oracle",
                  title: "Member probe",
                  description: "",
                  state: "open",
                  revision: 1,
                  createdAt: "2026-01-01",
                  updatedAt: "2026-01-01",
                  deletedAt: null,
                  fields: {},
                } satisfies Task,
                action: "__host_unknown_action",
                input: {},
              },
              member.pluginId,
            );
